export function buildManifest(rowsText = directedRows) {
  const sourceBytes = readFileSync(sourceUrl);
  const sourceSha = createHash('sha256').update(sourceBytes).digest('hex');
  if (sourceSha !== SOURCE_SHA) throw new Error('Immutable GETT source changed: review required');
  const cards = JSON.parse(sourceBytes);
  const rows = rowsText.trim().split('\n').filter(Boolean).map(line => line.split('|'));
  if (rows.some(row => row.length !== 6)) throw new Error('Every explicit art row needs six fields');
  const byId = new Map(rows.map(([n,...rest]) => [`RCN-${n}`,rest]));
  if (byId.size !== 300 || rows.length !== 300 || cards.length !== 300) throw new Error('Exactly 300 explicit unique rows and cards required');
  const allowed = new Set(['character','object','location','event','institution','action']);
  const briefs = cards.map(card => {
    const row = byId.get(card.id);
    if (!row || !allowed.has(row[0])) throw new Error(`Unreviewed scene ${card.id}`);
    const decision = interpretations[card.id];
    if (Boolean(reviewNotes[card.id]) !== Boolean(decision)) throw new Error(`Flag disposition missing or untracked: ${card.id}`);
    const interpretationReview = decision ? {
      status:decision.openQuestion ? 'OPEN_INTERPRETATION' : 'RESOLVED_BRIEF_INTERPRETATION_ONLY',
      owner:'Astra',
      sourceFacts:{name:card.name,kind:card.kind,subtype:card.subtype,series:card.series,effectText:card.text},
      sourceEvidence:['public/games/gett-oh/source-cards.json#'+card.id,...(decision.evidence || [])],
      initialConcern:reviewNotes[card.id][0],
      proposedSceneInterpretation:decision.scene,
      groundedDisposition:decision.disposition,
      noMechanicalClaim:decision.limit,
      openQuestion:decision.openQuestion || null,
      artAccepted:false,
      humanApproval:false,
    } : null;
    return { id:card.id, sourceCard:structuredClone(card), sceneClass:row[0], subjects:row[1], actionAndEffectBridge:row[2], setting:row[3], composition:row[4], status:'BRIEF_ONLY_NOT_ACCEPTED_ART', accepted:false, format:'original SVG/vector/layered render only', illustrationDimensions:[400,300], mechanicAuthority:'sourceCard.text is unchanged and authoritative; the image is a nonliteral scene, not a new effect', constraints:['Adult fictional people only; anatomically credible diverse cast','No real person, institution, logo, uniform, political emblem or real map','No generated raster, embedded image, traced photo, external asset or CDN','No visible title, motto, slogan, flavour text, labels or random letters inside artwork','No weapons, injury, violence or intimidation aesthetics','No shared-engine, card-data, UI-dimension, save or accessibility-text edits'], interpretationReview, unresolved:decision?.openQuestion ? [decision.openQuestion] : [] };
  });
  return { schemaVersion:1, game:'GETT-OH!', sourceSha256:SOURCE_SHA, preparation:true, acceptedArtCount:0, cardCount:300, authorship:'Explicit per-ID scene briefs after reading immutable card names/types/series/effects; no fallback classifier', interpretationReviewSummary:{reviewed:briefs.filter(b=>b.interpretationReview).length,resolvedAtBriefLevel:briefs.filter(b=>b.interpretationReview?.status==='RESOLVED_BRIEF_INTERPRETATION_ONLY').length,open:briefs.filter(b=>b.unresolved.length).length,noArtworkOrHumanApproval:true}, identity:{palette:['warm amber','dark brown','dirty cream','dark green'], materials:['aged timber','woven everyday fabric','tea glass','worn metal','matte paper'], light:'One plausible principal practical light per scene; background light only when scene requires it', tone:'Adult humane invented urban neighborhood, differentiated from VETO institutional daylight and DARBE archive noir'}, qualityGate:'BLOCKED: first vector probe failed photographic-realism target; briefs do not resolve execution quality', briefs };
}

